    [R("lab.creat", "Creatinine", 158, "umol/L", "45-90", "high", "Acute kidney injury stage 1 (1.9 times baseline)", ("82", "GP baseline"), 45, origin="book"), R("lab.urea", "Urea", 13.2, "mmol/L", "2.5-7.8", "high", "Pre-renal pattern", None, 45, origin="book"),
     R("lab.k", "Potassium", 3.0, "mmol/L", "3.5-5.3", "low", "Low after vomiting", None, 45), R("lab.wbc", "WBC", 16.5, "x10^9/L", "4.0-11.0", "high", "Raised", None, 45), R("lab.crp", "CRP", 112, "mg/L", "below 5", "high", "Raised", None, 45),
     R("lab.lactate", "Lactate", 2.4, "mmol/L", "below 2.0", "high", "Hypoperfusion", None, 30), R("lab.preg", "Pregnancy test", "Negative", "", "negative", "negative", "Not pregnant", None, 5)],
    [S("NEWS2", "4", "Low-risk tier by score (NG253) but clinical concern from the trend", "book")],
